('usr_luxury_04', 'Ananya Roy', 'ananya.luxury@gmail.com', '$2a$10$A1p4C2j7I6O2a3.h5y4pRhN0t1d4c2f5e6f7g8h9i0j1k2l3m', 'traveler', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=256&q=80', '+91 97112 34567', 'Gold', 8900, 'Feb 2024', 'Experiential luxury travel enthusiast, heritage palace stays & fine-dining connoisseur.'),
('usr_guide_05', 'Rajesh Kulkarni', 'rajesh.guide@tripcraft.io', '$2a$10$B2q5D3k8J7P3b4.i6z5qSiP1u2e5d3g6f7g8h9i0j1k2l3m', 'guide', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=256&q=80', '+91 99887 66554', 'Certified Partner', 6200, 'Nov 2023', 'Ministry of Tourism certified heritage guide for Rajasthan & Western Ghats with 12 yrs exp.');
INSERT INTO `destinations` (`id`, `name`, `state`, `tagline`, `category`, `hero_image`, `rating`, `reviews_count`, `base_price`, `best_time_to_visit`, `weather_temp`, `weather_condition`, `weather_humidity`, `safety_score`, `women_safe_score`, `description`, `highlights`, `suggested_duration`, `ideal_for`) VALUES
('dest_munnar', 'Munnar', 'Kerala', 'Rolling Emerald Tea Hills & Misty Waterfalls', 'Hill Station', 'https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=1200&q=80', 4.85, 1420, 4200.00, 'September – March', '18°C', 'Pleasant & Misty', '72%', 94, 92, 'Nestled at 1,600 meters in the Western Ghats of Kerala, Munnar is renowned for its sprawling tea estates, cool mountain breeze, rare Neelakurinji blossoms, and the highest peak in South India, Anamudi.', '["Kolukkumalai Sunrise Safari", "Eravikulam National Park (Nilgiri Tahr)", "Mattupetty Dam & Speedboating", "Tea Museum & Tasting"]', '3 - 4 Days', '["Solo Travelers", "Couples", "Family Trekkers"]'),
('dest_jaipur', 'Jaipur', 'Rajasthan', 'The Pink City of Palaces, Forts & Royal Splendor', 'Heritage', 'https://images.unsplash.com/photo-1603288940316-25f0a20ba967?auto=format&fit=crop&w=1200&q=80', 4.90, 2150, 3800.00, 'October – March', '26°C', 'Sunny & Crisp', '42%', 90, 89, 'The capital of Rajasthan, Jaipur forms the Golden Triangle along with Delhi and Agra. Marvel at the intricate honeycomb facade of Hawa Mahal, the hilltop ramparts of Amer Fort, and vibrant Johari Bazaar.', '["Amer Fort Elephant Pathway & Light Show", "Hawa Mahal & City Palace", "Jantar Mantar Astronomical Observatory", "Chokhi Dhani Rajasthani Cultural Dinner"]', '3 - 5 Days', '["Heritage Buffs", "Shoppers", "Families"]'),
('dest_ladakh', 'Leh Ladakh', 'Ladakh UT', 'High-Altitude Passes, Monasteries & Azure Lakes', 'Adventure', 'https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=1200&q=80', 4.95, 1890, 8500.00, 'May – September', '14°C', 'Clear Skies & UV High', '28%', 96, 95, 'The Roof of the World, Ladakh beckons adventure seekers with rugged mountains, dramatic Khardung La pass (17,582 ft), tranquil Tibetan Buddhist monasteries like Thiksey, and the color-changing Pangong Tso lake.', '["Pangong Tso Blue Water Camping", "Nubra Valley Bactrian Camel Safari", "Khardung La World Highest Motorable Pass", "Thiksey Monastery Sunrise Chants"]', '6 - 8 Days', '["Bikers", "Photographers", "Solo Adventurers"]'),
('dest_goa', 'South Goa', 'Goa', 'Serene Golden Sands, Portuguese Architecture & Sunset Shacks', 'Beach', 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=1200&q=80', 4.82, 3100, 3200.00, 'November – April', '29°C', 'Warm Breeze', '68%', 92, 90, 'Away from the bustling party strips of the north, South Goa preserves tranquil beaches like Palolem, Agonda, and Colva, accompanied by UNESCO heritage churches of Old Goa and fragrant spice plantations.', '["Palolem Kayaking & Dolphin Spotting", "Cabo de Rama Fort Cliff Views", "Fontainhas Latin Quarter Walking Tour", "Dudh Sagar Waterfalls Jeep Safari"]', '4 - 5 Days', '["Couples", "Solo Backpackers", "Foodies"]'),
('dest_andaman', 'Havelock Island', 'Andaman & Nicobar', 'Turquoise Waters, Coral Reefs & Radhanagar Sunsets', 'Island & Marine', 'https://images.unsplash.com/photo-1589136777351-fdc9c9cab193?auto=format&fit=crop&w=1200&q=80', 4.92, 940, 7200.00, 'October – May', '28°C', 'Tropical Ocean Breeze', '76%', 95, 94, 'Swaraj Dweep (Havelock) hosts Asia acclaimed Radhanagar Beach. A paradise for scuba diving and sea-walking through pristine coral banks, elephant training reserves, and bioluminescent night kayaking.', '["PADI Scuba Diving at Elephant Beach", "Radhanagar Beach World-Class Sunset", "Bioluminescence Kayaking Tour", "Kalapathar Beach Turquoise Coastline"]', '4 - 6 Days', '["Honeymooners", "Divers", "Nature Lovers"]'),
('dest_hampi', 'Hampi', 'Karnataka', 'UNESCO Boulder Landscapes & Vijayanagara Empire Relics', 'Heritage & Trekking', 'https://images.unsplash.com/photo-1600100397608-f010e42e1281?auto=format&fit=crop&w=1200&q=80', 4.88, 1120, 2800.00, 'October – March', '27°C', 'Dry & Sunny', '45%', 91, 89, 'A monumental open-air museum set among surreal boulder-strewn hills. Virupaksha Temple, the iconic Stone Chariot at Vittala Temple, and riverside coracle rides make Hampi an unmissable cultural wonder.', '["Vittala Temple Musical Pillars & Stone Chariot", "Tungabhadra River Coracle Crossing", "Matanga Hill Sunset Trek", "Hippie Island Bouldering & Cafes"]', '3 - 4 Days', '["Solo Backpackers", "Historians", "Photographers"]'),
('dest_varanasi', 'Varanasi', 'Uttar Pradesh', 'Eternal Ghats, Morning Ragas & Ganga Evening Aarti', 'Spiritual & Heritage', 'https://images.unsplash.com/photo-1561361513-2d000a50f0dc?auto=format&fit=crop&w=1200&q=80', 4.87, 2800, 2600.00, 'October – March', '22°C', 'Cool Breeze near River', '54%', 88, 86, 'One of the world oldest continually inhabited cities. Witness centuries of devotional chants, the spectacular Dashashwamedh Ghat Aarti, sunrise boat journeys, and the silk-weaving alleys of Kashi.', '["Sunrise Ganga Rowing Boat Ride", "Grand Evening Dashashwamedh Aarti", "Kashi Vishwanath Corridor Walk", "Banarasi Silk Weaver Workshops"]', '3 - 4 Days', '["Cultural Explorers", "Spiritual Seekers", "Photographers"]'),
('dest_rishikesh', 'Rishikesh', 'Uttarakhand', 'Yoga Capital of the World & Himalayan White-Water Rafting', 'Wellness & Adventure', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=1200&q=80', 4.86, 1670, 3100.00, 'September – May', '21°C', 'Fresh Mountain Air', '48%', 93, 92, 'Situated where the holy Ganga descends from the Shivalik Himalayas. Known globally for ashrams, certified yoga teacher retreats, India highest bungee jumping platform, and Grade III/IV river rafting.', '["16-km White-Water River Rafting & Cliff Jump", "Triveni Ghat Evening Maha Aarti", "Beatles Ashram Graffiti & Meditation Domes", "Mohan Chatti 83m Bungee Jump"]', '3 - 5 Days', '["Solo Travelers", "Adventure Groups", "Yoga Enthusiasts"]');
INSERT INTO `packages` (`id`, `destination_id`, `title`, `duration`, `base_adult_price`, `rating`, `reviews_count`, `image`, `theme`, `group_discount_threshold`, `group_discount_percent`, `inclusions`, `exclusions`, `itinerary`) VALUES
('pkg_munnar_tea_trails', 'dest_munnar', 'Munnar Misty Highland Trails & Tea Sanctuary', '4 Days / 3 Nights', 12499.00, 4.88, 320, 'https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80', 'Nature & Hill Station', 4, 10, '["3 Nights 4-Star Resort Stay", "Daily Buffet Breakfast & Dinner", "Private Chauffeur AC Cab for All Transfers", "Kolukkumalai Sunrise 4x4 Jeep Safari", "Eravikulam Park Entry & Guide Fee"]', '["Flight / Train tickets to Kochi", "Personal Laundry & Beverages", "Adventure Activity Camera Fees"]', '[{"day": 1, "title": "Arrival in Kochi & Scenic Drive to Munnar", "desc": "Pickup from Cochin Airport. Cheeyappara waterfalls stop. Check-in to resort, evening tea walk."}, {"day": 2, "title": "Eravikulam Flora-Fauna & Tea History", "desc": "Morning visit to Eravikulam National Park to spot Nilgiri Tahr. Afternoon Tata Tea Museum visit."}, {"day": 3, "title": "Kolukkumalai Sunrise Jeep Safari", "desc": "4:00 AM 4x4 Jeep journey above cloud bank. Visit Mattupetty Dam and Kundala Lake."}, {"day": 4, "title": "Spice Garden Walk & Departure", "desc": "Guided cardamom plantation walk. Transfer back to Kochi."}]'),
('pkg_jaipur_royal_heritage', 'dest_jaipur', 'Jaipur Royal Forts, Havelis & Culinary Splendor', '3 Days / 2 Nights', 9999.00, 4.92, 480, 'https://images.unsplash.com/photo-1603288940316-25f0a20ba967?auto=format&fit=crop&w=800&q=80', 'Heritage & Culture', 4, 12, '["2 Nights Heritage Haveli Stay with Pool", "Daily Royal Breakfast", "Licensed ASI Heritage Tour Guide", "All Monument Entry Tickets with Fast Track", "Chokhi Dhani Traditional Cultural Dinner"]', '["Airfare to Jaipur", "Personal Shopping Expenses", "Tips & Porterage"]', '[{"day": 1, "title": "Amer Fort, Jaigarh & Jal Mahal", "desc": "Explore Amber Fort Sheesh Mahal. Jaigarh Fort world largest cannon. Sunset at Jal Mahal."}, {"day": 2, "title": "Old City, Hawa Mahal & Observatories", "desc": "Morning photography at Hawa Mahal. City Palace and Jantar Mantar. Johari Bazaar artisanal walk."}, {"day": 3, "title": "Nahargarh Fort Sunrise & Departure", "desc": "Sunrise over Pink City from Nahargarh ramparts. Check-out and afternoon departure."}]'),
('pkg_ladakh_odyssey', 'dest_ladakh', 'Leh, Nubra Valley & Pangong Lake Grand Odyssey', '7 Days / 6 Nights', 28999.00, 4.96, 260, 'https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=800&q=80', 'Adventure & High Altitude', 4, 10, '["6 Nights Boutique Stays & Luxury Glamping", "MAP Plan (Breakfast & Dinner Included)", "Inner Line Permits & Environmental Fees", "Dedicated 4WD Scorpio with Driver", "Oxygen Cylinder for Emergencies"]', '["Flights to/from Leh (IXL)", "Camel ride charges in Nubra", "Personal Travel Insurance"]', '[{"day": 1, "title": "Arrive in Leh & Essential Acclimatization", "desc": "Airport pickup (11,500 ft). Strict rest day. Evening stroll to Shanti Stupa."}, {"day": 2, "title": "Indus Valley Monasteries", "desc": "Visit Shey Palace, Thiksey Monastery, and Magnetic Hill phenomenon."}, {"day": 3, "title": "Khardung La Pass to Nubra Sand Dunes", "desc": "Cross Khardung La pass (17,582 ft). Hunder Sand Dunes camel safari."}, {"day": 4, "title": "Diskit Buddha to Turtuk Baltic Village", "desc": "Diskit Monastery and journey along Shyok River to Turtuk border village."}, {"day": 5, "title": "Nubra to Pangong Tso via Shyok Route", "desc": "Scenic transit to Pangong Tso (14,270 ft). Azure sunset over the lake."}, {"day": 6, "title": "Pangong Sunrise to Leh via Chang La", "desc": "Morning lake photography. Return drive via Chang La (17,688 ft)."}, {"day": 7, "title": "Departure from Leh", "desc": "Airport drop with lifelong memories of the Himalayan desert."}]');
