INSERT INTO `photo_albums` (`id`, `title`, `author`, `author_avatar`, `destination`, `price`, `rating`, `sales_count`, `pages_count`, `cover_image`, `description`, `preview_pages`) VALUES
('alb_01', 'Munnar Mist & Tea Trails: Collector Visual Odyssey', 'Priya Sharma', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=256&q=80', 'Munnar, Kerala', 349.00, 4.95, 84, 16, 'https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80', 'High-resolution curated photo album featuring secret trails around Kolukkumalai, tea picker portraits, and rare morning misty cloud beds.', '[{"pageNo": 1, "title": "Cover: Clouds of Kolukkumalai", "image": "https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80", "caption": "Dawn breaks over South India highest tea estate."}]'),
('alb_02', 'Jaipur Royal Havelis & Amber Facades', 'Rajesh Kulkarni', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=256&q=80', 'Jaipur, Rajasthan', 499.00, 4.90, 112, 20, 'https://images.unsplash.com/photo-1603288940316-25f0a20ba967?auto=format&fit=crop&w=800&q=80', 'Architectural study of Sheesh Mahal mirror geometry, Hawa Mahal sandstone jharokhas, and hidden courtyards of the Pink City.', '[{"pageNo": 1, "title": "Hawa Mahal Golden Hour", "image": "https://images.unsplash.com/photo-1603288940316-25f0a20ba967?auto=format&fit=crop&w=800&q=80", "caption": "953 jharokhas catching morning sun."}]');
